-- bienvenida-videos-manual.sql
-- Actualiza el CUERPO del popup de bienvenida (ajuste 'bienvenida_videos') con el
-- manual de operación: 4 bloques + encuesta por video, máximo 3 reproducciones,
-- ventana de 72 h, resumen del tema antes del examen, y evaluación por tema.
-- El popup ya está sembrado, así que esto es un UPDATE (no un INSERT).

UPDATE public.ajustes
SET valor = jsonb_set(valor, '{cuerpo}', jsonb_build_object(
  'es', E'Nos alegra que inicies este camino. Que el Señor abra tu corazón y acompañe cada paso de tu preparación.\n\nAsí funciona tu formación:\n• Cada tema tiene 4 videos cortos (bloques A, B, C y D). Al terminar cada video respondes una breve encuesta (4 por tema).\n• Cada video puede verse un máximo de 3 veces y permanece disponible hasta 72 horas desde que lo abres.\n• Al terminar el bloque D verás un resumen del tema para repasar antes de tu evaluación.\n• La evaluación es por tema: necesitas 8 de 10 para aprobar y las lecciones se desbloquean en orden.\n• Cada día, al iniciar tu sesión, verás una oración. ¿Dudas de fe? Usa «Consultar a tu catequista». Libros y recursos: «Biblioteca». Problema técnico: «Soporte».\n\nAl concluir recibirás tu constancia. ¡Que Dios bendiga tu camino!',
  'en', E'We are glad you are beginning this journey. May the Lord open your heart and accompany every step of your preparation.\n\nHow your formation works:\n• Each topic has 4 short videos (blocks A, B, C and D). After each video you answer a short survey (4 per topic).\n• Each video can be played at most 3 times and stays available for up to 72 hours after you open it.\n• After block D you will see a topic review to go over before your evaluation.\n• The evaluation is per topic: you need 8 out of 10 to pass, and lessons unlock in order.\n• Each day, as you begin your session, a prayer appears. Questions about the faith? Use “Ask your catechist.” Books and resources: “Library.” Technical issue: “Support.”\n\nWhen you finish you will receive your certificate. May God bless your journey!',
  'fr', E'Nous sommes heureux que tu commences ce chemin. Que le Seigneur ouvre ton cœur et accompagne chaque pas de ta préparation.\n\nComment fonctionne ta formation :\n• Chaque thème a 4 courtes vidéos (blocs A, B, C et D). À la fin de chaque vidéo, tu réponds à un court questionnaire (4 par thème).\n• Chaque vidéo peut être lue 3 fois au maximum et reste disponible jusqu''à 72 heures après son ouverture.\n• Après le bloc D, tu verras une révision du thème avant ton évaluation.\n• L''évaluation est par thème : il faut 8 sur 10 pour réussir, et les leçons se déverrouillent dans l''ordre.\n• Chaque jour, au début de ta session, une prière apparaît. Des questions sur la foi ? « Consulter ton catéchiste ». Livres et ressources : « Bibliothèque ». Problème technique : « Support ».\n\nÀ la fin, tu recevras ton attestation. Que Dieu bénisse ton chemin !',
  'de', E'Wir freuen uns, dass du diesen Weg beginnst. Möge der Herr dein Herz öffnen und jeden Schritt deiner Vorbereitung begleiten.\n\nSo funktioniert deine Ausbildung:\n• Jedes Thema hat 4 kurze Videos (Blöcke A, B, C und D). Nach jedem Video beantwortest du eine kurze Umfrage (4 pro Thema).\n• Jedes Video kann höchstens 3-mal abgespielt werden und bleibt bis zu 72 Stunden nach dem Öffnen verfügbar.\n• Nach Block D siehst du eine Themen-Zusammenfassung zum Wiederholen vor deiner Bewertung.\n• Die Bewertung erfolgt pro Thema: Du brauchst 8 von 10 zum Bestehen, und die Lektionen werden der Reihe nach freigeschaltet.\n• Jeden Tag siehst du zu Beginn deiner Einheit ein Gebet. Fragen zum Glauben? „Deinen Katecheten fragen“. Bücher und Ressourcen: „Bibliothek“. Technisches Problem: „Support“.\n\nAm Ende erhältst du deine Bescheinigung. Gott segne deinen Weg!',
  'pt', E'Ficamos felizes por iniciares este caminho. Que o Senhor abra o teu coração e acompanhe cada passo da tua preparação.\n\nComo funciona a tua formação:\n• Cada tema tem 4 vídeos curtos (blocos A, B, C e D). Ao terminar cada vídeo respondes a uma breve avaliação de qualidade (4 por tema).\n• Cada vídeo pode ser reproduzido no máximo 3 vezes e fica disponível até 72 horas depois de o abrires.\n• Após o bloco D verás um resumo do tema para rever antes da tua avaliação.\n• A avaliação é por tema: precisas de 8 em 10 para aprovar e as lições desbloqueiam em ordem.\n• A cada dia, ao iniciar a tua sessão, verás uma oração. Dúvidas de fé? Usa «Consultar o teu catequista». Livros e recursos: «Biblioteca». Problema técnico: «Suporte».\n\nAo concluir receberás o teu certificado. Que Deus abençoe o teu caminho!',
  'it', E'Siamo felici che tu inizi questo cammino. Il Signore apra il tuo cuore e accompagni ogni passo della tua preparazione.\n\nCome funziona la tua formazione:\n• Ogni tema ha 4 brevi video (blocchi A, B, C e D). Al termine di ogni video rispondi a un breve sondaggio (4 per tema).\n• Ogni video può essere riprodotto al massimo 3 volte e resta disponibile fino a 72 ore dopo l''apertura.\n• Dopo il blocco D vedrai un riepilogo del tema da ripassare prima della tua valutazione.\n• La valutazione è per tema: servono 8 su 10 per superarla e le lezioni si sbloccano in ordine.\n• Ogni giorno, all''inizio della tua sessione, vedrai una preghiera. Dubbi di fede? Usa «Consulta il tuo catechista». Libri e risorse: «Biblioteca». Problema tecnico: «Supporto».\n\nAl termine riceverai il tuo attestato. Che Dio benedica il tuo cammino!'
))
WHERE clave = 'bienvenida_videos';
